import { Agent, Connector, ContentType, MessageRole, StreamEventType, Vendor, ModelTask, SuspendSignal, StorageRegistry, createFileContextStorage, FileCorrelationStorage, ContextCompactionStrategy } from '/Users/aantich/dev/oneringai/dist/index.js';
import { mkdtemp, rm, writeFile } from 'node:fs/promises';
import { join } from 'node:path';
import { tmpdir } from 'node:os';
const evidence=[];let completionChecks=0;
function provider(name, responses=[], native=false) {
 const requests=[];
 const generate=async o=> { requests.push(o); const output=responses.length ? responses.shift() : 'ACK'; const blocks=typeof output==='string' ? [{type:'message',role:'assistant',content:[{type:'output_text',text:output}]}] : output;
 return { id:'response-'+requests.length,object:'response',created_at:1,model:o.model,status:'completed',output:blocks,output_text:typeof output==='string'?output:'', usage:{input_tokens:10,output_tokens:2,total_tokens:12} }; };
 const value={name,capabilities:{text:true,images:false,videos:false,audio:false},generate,
 async *streamGenerate(o){const r=await generate(o);yield {type:StreamEventType.OUTPUT_TEXT_DELTA,response_id:r.id,item_id:'text',output_index:0,content_index:0,sequence_number:1,delta:r.output_text};yield {type:StreamEventType.RESPONSE_COMPLETE,response_id:r.id,status:'completed',usage:r.usage,iterations:1};},
 getModelCapabilities:()=>({supportsTools:true,supportsVision:false,supportsJSON:true,supportsJSONSchema:true,maxTokens:16000,maxInputTokens:16000,maxOutputTokens:512}),validateConfig:async()=>true,listModels:async()=>[],
 ...(native?{compaction:{countInput:async()=>100,compact:async()=>({protocol:'review-native',input:[{type:'compaction',id:'compact',encrypted_content:'opaque'}],usage:{input_tokens:50,output_tokens:10,total_tokens:60}})}}:{})};
 return {value,requests};
}
const features={workingMemory:false,inContextMemory:false};
const directory=await mkdtemp(join(tmpdir(),'routing-review-'));
try {
 StorageRegistry.configure({sessions:id=>createFileContextStorage(id,{baseDirectory:directory}),correlations:new FileCorrelationStorage({baseDirectory:join(directory,'correlations')})});
 const toolOutput=[{type:'message',role:'assistant',content:[{type:'tool_use',id:'wait-1',name:'wait_event',arguments:'{}'}]}];
 const p=provider('review-suspend',[toolOutput,'{"answer":"pending"}','NOT_JSON','{"answer":"repaired"}']);
 Connector.create({name:'review-suspend',vendor:Vendor.OpenAI,auth:{type:'none'},options:{provider:p.value}});
 const agent=Agent.create({loopPolicy:{completion:()=>{completionChecks++;return {complete:true};}},connector:'review-suspend',model:'main',context:{model:'main',features},modelExecution:{customProviderAttempts:'single',routing:{routes:{fast:{model:'fast'}},select:()=> 'fast'}},tools:[{definition:{type:'function',function:{name:'wait_event',description:'wait',parameters:{type:'object',properties:{}}}},execute:async()=>SuspendSignal.create({result:'waiting',correlationId:'review:event'})}]});
 try {
 const format={type:'json_schema',name:'answer',strict:true,schema:{type:'object',properties:{answer:{type:'string'}},required:['answer'],additionalProperties:false}};
 const first=await agent.run('Wait then answer JSON',{responseFormat:format});
 completionChecks=0;const second=await agent.run('The external event arrived');
 evidence.push({id:'suspended-output-format',resumedCompletionChecks:completionChecks,resumedLoop:second.loop,initial:{status:first.status,parsed:first.output_parsed},resumed:{status:second.status,text:second.output_text,parsed:second.output_parsed??null,route:second.routing},providerRequests:p.requests.map(r=>({model:r.model,hasSchema:!!r.response_format})),calls:agent.getModelUsage()?.totals.calls});
 }finally{agent.destroy();}
 StorageRegistry.reset();
 for(const nativeDefault of [false,true]){
 const a=provider('review-default-'+nativeDefault,[],nativeDefault),b=provider('review-alternative-'+nativeDefault,[],true);
 Connector.create({name:'review-default-'+nativeDefault,vendor:Vendor.Google,auth:{type:'none'},options:{provider:a.value}});
 Connector.create({name:'review-alternative-'+nativeDefault,vendor:Vendor.Anthropic,auth:{type:'none'},options:{provider:b.value}});
 let agent;
 try {agent=Agent.create({connector:'review-default-'+nativeDefault,model:'main',context:{model:'main',features:{...features,evidence:true},compactionStrategy:new ContextCompactionStrategy({plugins:'off',history:'native'})},modelExecution:{customProviderAttempts:'single',routing:{routes:{native:{connector:'review-alternative-'+nativeDefault,model:'alternative',allowContextTransfer:true}},select:()=> 'native'}}});await agent.run('Use the supported native route');evidence.push({id:'native-default-construction',nativeDefault,created:true,selected:agent.getRoutingDiagnostics(),defaultCalls:a.requests.length,alternativeCalls:b.requests.length});}
 catch(error){evidence.push({id:'native-default-construction',nativeDefault,created:false,error:error.message,defaultCalls:a.requests.length,alternativeCalls:b.requests.length});}
 finally{agent?.destroy();}
 }
} finally {StorageRegistry.reset();Connector.clear();await rm(directory,{recursive:true,force:true});}
await writeFile('/tmp/oneringai-stage14-review-probes.json',JSON.stringify(evidence,null,2)+'\n');
console.log(JSON.stringify(evidence,null,2));

import { Agent, Connector, Vendor } from '/Users/aantich/dev/oneringai/dist/index.js';
import {writeFile} from 'node:fs/promises';
const calls=[];let opaque=true;
const provider={name:'replay-review',capabilities:{text:true,images:false,videos:false,audio:false},async generate(o){calls.push(o);const output=[...(opaque?[{type:'reasoning',id:'r',encrypted_content:'OPAQUE_FAST_STATE'}]:[]),{type:'message',role:'assistant',content:[{type:'output_text',text:'ACK'}]}];opaque=false;return {id:'r',object:'response',created_at:1,status:'completed',model:o.model,output,output_text:'ACK',usage:{input_tokens:10,output_tokens:2,total_tokens:12}};},async *streamGenerate(){throw new Error('unused');},getModelCapabilities:()=>({supportsTools:true,supportsVision:false,supportsJSON:true,supportsJSONSchema:true,maxTokens:16000,maxInputTokens:16000,maxOutputTokens:512}),validateConfig:async()=>true,listModels:async()=>[]};
Connector.create({name:'replay-review',vendor:Vendor.OpenAI,auth:{type:'none'},options:{provider}});
const common={connector:'replay-review',context:{model:'fast',features:{workingMemory:false,inContextMemory:false}},modelExecution:{customProviderAttempts:'single'}};
const a=Agent.create({...common,model:'main',modelExecution:{...common.modelExecution,routing:{routes:{fast:{model:'fast'}},select:()=> 'fast'}}});
const report=[];let b,c;
try{
 await a.run('produce signed state'); const state=structuredClone(a.context.getState());
 b=Agent.create({...common,model:'fast'});b.context.restoreState(structuredClone(state));b.on('llm:request',event=>{event.options.model='different-model';});
 const before=calls.length;await b.run('continue checkpoint');report.push({id:'disabled-routing-replay-hook',savedOrigin:state.providerStateBinding,dispatched:calls.length-before,actualModel:calls.at(-1).model,opaqueTransferred:JSON.stringify(calls.at(-1).input).includes('OPAQUE_FAST_STATE')});
 c=Agent.create({...common,model:'fast',modelExecution:{...common.modelExecution,routing:{routes:{}}}});c.context.restoreState(structuredClone(state));c.on('llm:request',event=>{event.options.model='different-model';});
 try{await c.run('control');report.push({id:'enabled-routing-control',blocked:false});}catch(error){report.push({id:'enabled-routing-control',blocked:true,error:error.message});}
}finally{a.destroy();b?.destroy();c?.destroy();Connector.clear();}
await writeFile('/tmp/oneringai-stage14-review-replay.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report,null,2));

